use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse, middleware};
use serde::Deserialize;
use url::Url;
use std::collections::HashSet;

#[derive(Deserialize)]
struct OAuthParams {
    client_id: String,
    redirect_uri: String,
    response_type: String,
    state: Option<String>,
    scope: Option<String>,
}

struct AppState {
    registered_clients: HashSet<String>,
    // Only the domain is validated, not the full URI path
    allowed_redirect_domains: HashSet<String>,
}

fn validate_redirect_uri(uri: &str, allowed_domains: &HashSet<String>) -> bool {
    // Parse the redirect_uri and check if the host matches allowed domains
    match Url::parse(uri) {
        Ok(parsed) => {
            if let Some(host) = parsed.host_str() {
                // Check if the host ends with any allowed domain
                // This is intentionally vulnerable to subdomain tricks
                for domain in allowed_domains {
                    if host.ends_with(domain) {
                        return true;
                    }
                }
            }
            false
        }
        Err(_) => false,
    }
}

async fn authorize(
    query: web::Query<OAuthParams>,
    data: web::Data<AppState>,
) -> HttpResponse {
    // Verify client_id is registered
    if !data.registered_clients.contains(&query.client_id) {
        return HttpResponse::BadRequest().json(serde_json::json!({
            "error": "invalid_client",
            "error_description": "Unknown client_id"
        }));
    }

    // Validate redirect_uri against allowed domains
    if !validate_redirect_uri(&query.redirect_uri, &data.allowed_redirect_domains) {
        return HttpResponse::BadRequest().json(serde_json::json!({
            "error": "invalid_redirect_uri",
            "error_description": "Redirect URI not allowed"
        }));
    }

    // Validate response_type
    if query.response_type != "code" && query.response_type != "token" {
        return HttpResponse::BadRequest().json(serde_json::json!({
            "error": "unsupported_response_type"
        }));
    }

    // Generate authorization code (simplified)
    let auth_code = "generated_auth_code_abc123";
    let state_param = query.state.as_deref().unwrap_or("");

    // Redirect to the client's redirect_uri with the auth code
    let redirect_url = format!(
        "{}?code={}&state={}",
        query.redirect_uri, auth_code, state_param
    );

    HttpResponse::Found()
        .append_header(("Location", redirect_url.as_str()))
        .finish()
}

async fn health() -> HttpResponse {
    HttpResponse::Ok().json(serde_json::json!({"status": "healthy"}))
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let mut registered_clients = HashSet::new();
    registered_clients.insert("app-client-001".to_string());
    registered_clients.insert("app-client-002".to_string());

    let mut allowed_redirect_domains = HashSet::new();
    allowed_redirect_domains.insert(".myapp.com".to_string());
    allowed_redirect_domains.insert(".trusted-partner.io".to_string());

    let app_state = web::Data::new(AppState {
        registered_clients,
        allowed_redirect_domains,
    });

    HttpServer::new(move || {
        App::new()
            .app_data(app_state.clone())
            .route("/oauth/authorize", web::get().to(authorize))
            .route("/health", web::get().to(health))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
